CREATE TABLE IF NOT EXISTS social_schema_versions(version TEXT PRIMARY KEY, migrated_at TEXT NOT NULL, scope_digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS acquisition_sources(source_id TEXT PRIMARY KEY, base_url TEXT, source_region TEXT, public_access TEXT, local_retention TEXT, redistribution TEXT, policy_evidence_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS acquisition_interfaces(interface_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES acquisition_sources, documented_url TEXT NOT NULL, endpoint_family TEXT NOT NULL, adapter TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS acquisition_frames(frame_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES acquisition_sources, frame_type TEXT NOT NULL, selection_rule TEXT NOT NULL, existence_lower_bound TEXT, actor_role_basis TEXT, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS native_entities(entity_id TEXT PRIMARY KEY, source_id TEXT NOT NULL, native_namespace TEXT NOT NULL, native_id TEXT NOT NULL, source_url TEXT, native_unit TEXT NOT NULL, native_created_at TEXT, date_precision TEXT NOT NULL, author_id TEXT, author_role TEXT NOT NULL, author_country TEXT, first_retrieved_at TEXT NOT NULL, inherited INTEGER NOT NULL DEFAULT 0, UNIQUE(source_id,native_namespace,native_id));
CREATE TABLE IF NOT EXISTS entity_versions(entity_version_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES native_entities, core_body_version_id TEXT REFERENCES versions(body_version_id), body_original TEXT, body_text TEXT, body_sha256 TEXT, native_edited_at TEXT, native_revision TEXT, content_state TEXT NOT NULL, fixed_interval_state TEXT NOT NULL, readable_native_unit INTEGER NOT NULL, independently_authored_body INTEGER NOT NULL, content_license TEXT, licence_basis TEXT, flags_json TEXT NOT NULL, native_fields_json TEXT NOT NULL, first_retrieved_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entity_observations(entity_version_id TEXT NOT NULL REFERENCES entity_versions, request_id TEXT NOT NULL REFERENCES responses, frame_id TEXT, retrieved_at TEXT NOT NULL, PRIMARY KEY(entity_version_id,request_id,frame_id));
CREATE TABLE IF NOT EXISTS native_edges(edge_id TEXT PRIMARY KEY, source_entity_id TEXT NOT NULL REFERENCES native_entities, relation_type TEXT NOT NULL, target_source_id TEXT, target_namespace TEXT, target_native_id TEXT, target_entity_id TEXT REFERENCES native_entities, target_url TEXT, resolution_state TEXT NOT NULL, native_fields_json TEXT NOT NULL, first_request_id TEXT, first_retrieved_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS native_attachments(attachment_id TEXT PRIMARY KEY, entity_version_id TEXT NOT NULL REFERENCES entity_versions, native_attachment_id TEXT, attachment_type TEXT NOT NULL, source_url TEXT, availability TEXT NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS structural_corrections(correction_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, field TEXT NOT NULL, prior_value TEXT, derived_value TEXT, evidence_json TEXT NOT NULL, corrected_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS entity_dates ON native_entities(source_id,native_created_at);
CREATE INDEX IF NOT EXISTS entity_body_hash ON entity_versions(body_sha256);
CREATE INDEX IF NOT EXISTS unresolved_edge_targets ON native_edges(target_source_id,target_namespace,target_native_id);
